j.textContent="      window.pdfjsLib.GlobalWorkerOptions.workerSrc =\n        'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';\n      window.renderPdfFirstPage = async function(bytes) {\n        const source = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);\n        const pdfDocument = await window.pdfjsLib.getDocument({\n          data: source,\n          cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/cmaps/',\n          cMapPacked: true,\n          standardFontDataUrl:\n            'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/standard_fonts/',\n          useSystemFonts: true,\n          disableFontFace: false,\n          fontExtraProperties: true\n        }).promise;\n        const page = await pdfDocument.getPage(1);\n        // PDF.js registers embedded fonts while preparing the operator list.\n        // Waiting for both stages prevents Japanese text from being omitted\n        // when the canvas is converted to PNG immediately after rendering.\n        await page.getOperatorList({intent: 'display'});\n        if (document.fonts && document.fonts.ready) {\n          await document.fonts.ready;\n        }\n        const viewport = page.getViewport({scale: 2});\n        const canvas = document.createElement('canvas');\n        canvas.width = Math.ceil(viewport.width);\n        canvas.height = Math.ceil(viewport.height);\n        const context = canvas.getContext('2d', {alpha: false});\n        context.fillStyle = '#ffffff';\n        context.fillRect(0, 0, canvas.width, canvas.height);\n        await page.render({\n          canvasContext: context,\n          viewport: viewport,\n          intent: 'display'\n        }).promise;\n        return canvas.toDataURL('image/png');\n      };\n      window.renderPdfAllPages = async function(bytes) {\n        const source = bytes instanceof Uint8Array ? bytes.slice() : new Uint8Array(bytes);\n        const pdfDocument = await window.pdfjsLib.getDocument({\n          data: source,\n          cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/cmaps/',\n          cMapPacked: true,\n          standardFontDataUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/standard_fonts/',\n          useSystemFonts: true,\n          disableFontFace: false\n        }).promise;\n        const pages = [];\n        for (let pageNumber = 1; pageNumber <= pdfDocument.numPages; pageNumber++) {\n          const page = await pdfDocument.getPage(pageNumber);\n          await page.getOperatorList({intent: 'display'});\n          const textContent = await page.getTextContent();\n          const pageText = textContent.items\n            .map(item => typeof item.str === 'string' ? item.str : '')\n            .join(' ')\n            .replace(/\u3000/g, ' ');\n          const normalizedText = pageText\n            .replace(/[\uff33\uff53]/g, 'S')\n            .replace(/[\uff1d]/g, '=')\n            .replace(/[\uff1a]/g, ':')\n            .replace(/[\uff0f]/g, '/');\n          const scaleMatch = normalizedText.match(\n            /(?:^|[^A-Za-z])S\\s*(?:[:=]\\s*)?(?:1\\s*[/:]\\s*)?(\\d+(?:\\.\\d+)?)/i\n          );\n          const detectedScale = scaleMatch ? Number(scaleMatch[1]) : null;\n          // The list is only a page navigator. Keep these images modest and\n          // render one selected page again from the original PDF when zoomed.\n          // Two-column page cards are large enough to benefit from a sharper\n          // source. Scale 3 remains materially lighter than the former scale\n          // 4 all-page render while preserving small CAD text in the list.\n          const viewport = page.getViewport({scale: 3});\n          const canvas = document.createElement('canvas');\n          canvas.width = Math.ceil(viewport.width);\n          canvas.height = Math.ceil(viewport.height);\n          const context = canvas.getContext('2d', {alpha: false});\n          context.fillStyle = '#ffffff';\n          context.fillRect(0, 0, canvas.width, canvas.height);\n          await page.render({canvasContext: context, viewport, intent: 'display'}).promise;\n          pages.push({\n            dataUrl: canvas.toDataURL('image/png'),\n            detectedScale: Number.isFinite(detectedScale) ? detectedScale : null\n          });\n          await new Promise(resolve => setTimeout(resolve, 0));\n        }\n        return JSON.stringify(pages);\n      };\n      window.renderPdfPageHighResolution = async function(bytes, pageNumber, requestedScale) {\n        const source = bytes instanceof Uint8Array ? bytes.slice() : new Uint8Array(bytes);\n        const pdfDocument = await window.pdfjsLib.getDocument({\n          data: source,\n          cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/cmaps/',\n          cMapPacked: true,\n          standardFontDataUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/standard_fonts/',\n          useSystemFonts: true,\n          disableFontFace: false\n        }).promise;\n        const page = await pdfDocument.getPage(pageNumber);\n        await page.getOperatorList({intent: 'display'});\n        if (document.fonts && document.fonts.ready) await document.fonts.ready;\n        const base = page.getViewport({scale: 1});\n        // A single canvas edge above this is unreliable on iPad Safari.\n        // Use the highest safe scale for this page instead of rendering every\n        // page at the same oversized resolution.\n        const safeScale = Math.max(1, Math.min(Number(requestedScale) || 6,\n          10000 / Math.max(base.width, base.height)));\n        const viewport = page.getViewport({scale: safeScale});\n        const canvas = document.createElement('canvas');\n        canvas.width = Math.ceil(viewport.width);\n        canvas.height = Math.ceil(viewport.height);\n        const context = canvas.getContext('2d', {alpha: false});\n        context.fillStyle = '#ffffff';\n        context.fillRect(0, 0, canvas.width, canvas.height);\n        await page.render({canvasContext: context, viewport, intent: 'display'}).promise;\n        return canvas.toDataURL('image/png');\n      };\n    "
